data.value:
body {
	padding: 20px 20px 95px 20px;
	margin-top: 70px;
}
.shadow {	
	border-radius: 14px;
	box-shadow: 0px 0px 10px 0px rgba(0, 0, 0, 0.4);
}
.logo {
	position: absolute;
	top: 10px;
	left:50%;
	display: flex;
  	justify-content: center;
  	align-items: center;
	margin: auto;
	width: 150px;
	height: 150px;
	border-radius: 90px;
	background-color: @Control;
	box-shadow: 0px 6px 10px 0px rgba(0, 0, 0, 0.5);
	border: 1px solid rgba(0, 0, 0, 0.2);
	margin-left: -75px;
}
.logo-mask {
	width: 140px;
	height: 140px;
 	border-radius: 70px;
 	background-image: url("logo");
	background-position: center;
	background-repeat: no-repeat;
	background-size: 105%;
}
.close {
	width: 22px;
	height: 22px;
	border-radius: 5px;
	display: flex;
  	justify-content: center;
  	align-items: center;
  	margin: 8px;
}
.close:hover {
	background-color: @Black/0.2;	
}
.close-img {
	fill: @Black/0.4;
	width: 16px;
	height: 16px;
}
.frame{

	height: 100%;
	display: flex;
	flex-direction: column;
	align-items: flex-end;
	border-radius: 14px;
	border: 1px solid rgba(0, 0, 0, 0.2);
	background-color: @Control;

}
.content {
	margin-top: 60px;
	flex-grow: 1;
	width: 100%;
	height: 100%;
}

.footerbar{
	align-items: center;
	display: flex;
	flex-direction: row;
	background-color: @ControlText/0.05;
	border-radius: 0px 0px 13px 13px;
}
.button {
	height: 50px;
	width: 100%;	
	font-family: 'Segoe UI Light';
	font-weight: bold;
	font-size: 18px;
	display: flex; 
	align-items: center;
	justify-content: center;
	border-radius: 0px 0px 13px 13px;		
}
.button:hover{
	background-color: @Primary;
	color: @Text;
}

body {
	padding: 35px;
}
.shadow {
	border-radius: 14px;

}
.frame {
	height: 100%;
	display: flex;
	flex-direction: column;
	border-radius: 14px;
	border: 1px solid rgba(0, 0, 0, 0.2);
	background-color: @White;
	box-shadow: 0px 0px 8px 0px rgba(0, 0, 0, 0.2);
}
.header{
	padding: 11px 12px 11px 11px;
	display: flex;
	justify-content: space-between;
	flex-direction: row;
	height: 25px;
}
.header-text{
	display: flex;
	flex-direction: row;
	font-size: 11pt;
	font-family: 'Segoe UI';
	margin-left: 5px;
}
.close-button {
	width: 16px;
	height: 16px;
	border-radius: 5px;
	padding: 5px;
	background-color: @Danger/0.7;
  fill:@White;
}
.close-button:hover {
	background-color: @Danger;
}
.content {
	flex-grow: 1;
}
.buttons {
	border-top: 1px solid @Black/0.1;
	border-radius: 0px 0px 14px 14px;
	background-color: @Control;
	display: flex;
	flex-direction: row;
	justify-content: center;
}
.button{
	width: 150px;
	margin: 25px 5px 25px 5px;
	padding: 5px;
	border-radius: 4px;
    background-color: @White;
    color: @WindowText;
    font-size: 10pt;
    font-family: 'Segoe UI';
    border: 1px solid @Black/0.15;
    text-align: center;
}
.button:hover{
	background-color: @Black/0.1;
}
.button:focus{
	background-color: @HighlightAlternate;
	border: 1px solid @HighlightAlternate;
	color: @White;
}

.content {
	padding: 30px 30px 10px 30px;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
}
.input-box {
	display: flex;
	align-items: center;
	padding: 6px;
	margin: 4px;
	background-color: @Window;
	border: 1px solid rgba(80, 80, 80, 0.25);
	border-radius: 6px;
}
.img { 
	width: 16px;
	height: 16px;
	margin: 2px 4px;
}
.input {
	color: @DisabledText;
	flex-grow: 1;
	background-color: @Window;
	height: 22px;
	cursor: text;
}
.link {	
	margin-right: 5px;
	margin-bottom: 3px;
	font-family: "Segoe UI Light";
	font-size: 9pt;
}

.content {
	padding: 10px 20px;
	text-align: center;
}
.logo {
	margin: 5px;
	width: 100px;
	height: 100px;
}
.rating-box {
	padding: 10px 0px;
}
.rating { 
	background-color: @Control;
}
.input-box { 
	display: flex;
	margin: 8px 0px;
	padding: 10px 14px;
	background-color: @Window;
	border: 1px solid rgba(80, 80, 80, 0.25);
	border-radius: 6px;
}
.feedback {
	flex-grow: 1;
	height: 60px;
	color: @DisabledText;
	background-color: @Window;
	cursor: text;
}
